import 'package:flutter/material.dart';
import '../../core/services/lecturador_service.dart';

class RegistrarLecturaPage extends StatefulWidget{const RegistrarLecturaPage({super.key});@override State<RegistrarLecturaPage> createState()=>_RegistrarLecturaPageState();}
class _RegistrarLecturaPageState extends State<RegistrarLecturaPage>{static const Color primary=Color(0xFF0F3D57), secondary=Color(0xFF1DA1C2), background=Color(0xFFEFF7FB), muted=Color(0xFF7B8794); final LecturadorService service=LecturadorService(); final lecturaController=TextEditingController(); final obsController=TextEditingController(); bool cargando=false; String error=''; Map<String,dynamic>? suministro; @override void didChangeDependencies(){super.didChangeDependencies();final a=ModalRoute.of(context)?.settings.arguments;if(a is Map<String,dynamic> && suministro==null){suministro=a;}} @override void dispose(){lecturaController.dispose();obsController.dispose();super.dispose();} String _txt(dynamic v,[String f='-']){if(v==null)return f;final s=v.toString().trim();return s.isEmpty||s=='null'?f:s;} double _num(dynamic v)=>v is num?v.toDouble():double.tryParse('$v')??0; Future<void> registrar()async{final s=suministro;if(s==null||s.isEmpty){setState(()=>error='Primero busca un suministro.');return;}final lectura=double.tryParse(lecturaController.text.trim().replaceAll(',','.'));if(lectura==null){setState(()=>error='Ingresa una lectura válida.');return;}final now=DateTime.now();setState(()=>{cargando=true,error=''});try{final resp=await service.registrarLectura(codigoSuministro:_txt(s['codigoSuministro']??s['codigo']),anio:now.year,mes:now.month,lecturaActual:lectura,observacion:obsController.text.trim());if(!mounted)return;setState(()=>cargando=false);Navigator.pushNamed(context,'/comprobante-recibo',arguments:resp);}catch(e){if(!mounted)return;setState(()=>{error=e.toString().replaceFirst('Exception: ',''),cargando=false});}}
@override Widget build(BuildContext context){final s=suministro;return Scaffold(backgroundColor:background,bottomNavigationBar:_LectorBottomNav(currentIndex:2,onTap:(i){if(i==0)Navigator.pushReplacementNamed(context,'/lector-home');if(i==1)Navigator.pushReplacementNamed(context,'/buscar-suministro');if(i==3)Navigator.pushReplacementNamed(context,'/historial-lecturas');}),body:SafeArea(child:SingleChildScrollView(padding:const EdgeInsets.all(22),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[IconButton(onPressed:()=>Navigator.pop(context),icon:const Icon(Icons.arrow_back_rounded,color:primary)),const Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Registro de lectura',style:TextStyle(color:muted,fontWeight:FontWeight.w700)),Text('Nueva lectura',style:TextStyle(color:primary,fontSize:24,fontWeight:FontWeight.w900))]))]),const SizedBox(height:18),if(s==null||s.isEmpty)Container(width:double.infinity,padding:const EdgeInsets.all(18),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(22)),child:Column(children:[const Text('No hay suministro seleccionado.',style:TextStyle(color:primary,fontWeight:FontWeight.w900)),const SizedBox(height:10),ElevatedButton(onPressed:()=>Navigator.pushReplacementNamed(context,'/buscar-suministro'),child:const Text('Buscar suministro'))]))else Container(width:double.infinity,padding:const EdgeInsets.all(18),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(24)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(_txt(s['codigoSuministro']??s['codigo']),style:const TextStyle(color:primary,fontSize:20,fontWeight:FontWeight.w900)),Text(_txt(s['direccionSuministro']),style:const TextStyle(color:muted)),const SizedBox(height:16),TextField(controller:lecturaController,keyboardType:TextInputType.number,decoration:InputDecoration(labelText:'Lectura actual',hintText:'Lectura inicial: ${_num(s['lecturaInicial']).toStringAsFixed(0)}',border:OutlineInputBorder(borderRadius:BorderRadius.circular(16)))),const SizedBox(height:12),TextField(controller:obsController,decoration:InputDecoration(labelText:'Observación',border:OutlineInputBorder(borderRadius:BorderRadius.circular(16)))),if(error.isNotEmpty)Padding(padding:const EdgeInsets.only(top:12),child:Text(error,style:const TextStyle(color:Color(0xFFD93025),fontWeight:FontWeight.w800))),const SizedBox(height:18),SizedBox(width:double.infinity,height:52,child:ElevatedButton.icon(onPressed:cargando?null:registrar,icon:cargando?const SizedBox(width:18,height:18,child:CircularProgressIndicator(strokeWidth:2,color:Colors.white)):const Icon(Icons.receipt_long_rounded),label:Text(cargando?'Generando...':'Generar recibo'),style:ElevatedButton.styleFrom(backgroundColor:secondary,foregroundColor:Colors.white)))]))]))));}}
class _LectorBottomNav extends StatelessWidget{final int currentIndex;final Function(int) onTap;const _LectorBottomNav({required this.currentIndex,required this.onTap});@override Widget build(BuildContext context)=>NavigationBar(selectedIndex:currentIndex,onDestinationSelected:onTap,height:76,destinations:const[NavigationDestination(icon:Icon(Icons.home_outlined),label:'Inicio'),NavigationDestination(icon:Icon(Icons.qr_code_rounded),label:'QR'),NavigationDestination(icon:Icon(Icons.water_drop_rounded),label:'Lectura'),NavigationDestination(icon:Icon(Icons.history_rounded),label:'Historial')]);}
